import Model from 'flarum/common/Model';

/** A member's birthday (`fanfare-birthdays`, id = the user's id), as Settings → Fanfare reads and saves it. */
export default class Birthday extends Model {
  md = Model.attribute('md');
  year = Model.attribute('year');
  visibility = Model.attribute('visibility');
}
flarum.reg.add('ernestdefoe-fanfare', 'forum/models/Birthday', Birthday);